def nth_super_ugly_number(n, primes):
    import heapq
    uglies = [1]
    seen = set(uglies)
    heap = []
    for prime in primes:
        heapq.heappush(heap, (prime, prime, 0))
    while len(uglies) < n:
        ugly, prime, idx = heapq.heappop(heap)
        if ugly not in seen:
            uglies.append(ugly)
            seen.add(ugly)
            for p in primes:
                new_ugly = ugly * p
                heapq.heappush(heap, (new_ugly, p, idx+1))
    return uglies[-1]

