def comb_sort(nums):
    gap = len(nums)
    shrink_factor = 1.3
    sorted = False
    while not sorted:
        gap = int(gap / shrink_factor)
        if gap <= 1:
            gap = 1
            sorted = True
        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted = False
    return nums

def magic_square_test(square):
    n = len(square)
    target_sum = n * (n**2 + 1) // 2

    # Check rows
    for row in square:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != target_sum:
            return False

    # Check diagonals
    if sum(square[i][i] for i in range(n)) != target_sum:
        return False
    if sum(square[i][n-i-1] for i in range(n)) != target_sum:
        return False

    return True

