def find_last_occurrence(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] <= target:
            left = mid + 1
        else:
            right = mid - 1
    return left - 1 if left - 1 >= 0 and nums[left - 1] == target else -1

