def second_frequent(lst):
    counts = {}
    for word in lst:
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1
    max_count = max(counts.values())
    max_key = max(counts, key=counts.get)
    del counts[max_key]
    second_max_count = max(counts.values())
    for key, value in counts.items():
        if value == second_max_count:
            return key

