def check_subset(nested_list, subset):
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    subset_flat = set(flatten(subset))
    nested_list_flat = set(flatten(nested_list))

    return subset_flat.issubset(nested_list_flat)

